class Solution {
    public ListNode rotateRight(ListNode head, int k) {
        if (head == null || head.next == null) return head;
        int length = 1;
        ListNode tail = head;
        while (tail.next != null) { tail = tail.next; length++; }
        int rotations = k % length;
        for (int count = 0; count < rotations; count++) {
            ListNode previous = head;
            while (previous.next != tail) previous = previous.next;
            tail.next = head;
            head = tail;
            previous.next = null;
            tail = previous;
        }
        return head;
    }
}

